import type { BankQuestion } from "@/lib/bank";

/** Corporate Finance & Financial Markets (Management & Commerce): 200 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-finance-1","question":"₹10,000 is invested at 8% per annum compounded annually. What is it worth after 3 years?","options":["₹12,400.00","₹12,653.19","₹12,597.12","₹11,664.00"],"answer":2,"explanation":"FV = 10,000 × 1.08³ = 10,000 × 1.259712 = ₹12,597.12. ₹12,400 is simple interest; ₹12,653.19 assumes half-yearly compounding.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-2","question":"What is the present value of ₹50,000 receivable at the end of 2 years if the discount rate is 10% per annum?","options":["₹41,322.31","₹40,000.00","₹41,666.67","₹45,454.55"],"answer":0,"explanation":"PV = 50,000 / 1.1² = 50,000 / 1.21 = ₹41,322.31. Dividing by 1.2 ignores compounding; dividing by 1.1 discounts only one year.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-3","question":"A preference-like security pays ₹6,000 at the end of every year forever. If the required return is 12%, what is its value today?","options":["₹72,000","₹44,642.86","₹56,000","₹50,000"],"answer":3,"explanation":"PV of a perpetuity = C / r = 6,000 / 0.12 = ₹50,000. ₹56,000 would be a perpetuity due (first payment today); dividing 50,000 by 1.12 again double-counts the one-year wait.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-4","question":"A credit line charges 12% per annum compounded monthly. What is its effective annual rate (EAR)?","options":["12.00%","12.68%","12.36%","12.75%"],"answer":1,"explanation":"EAR = (1 + 0.12/12)¹² − 1 = 1.01¹² − 1 = 12.68%. 12.36% is half-yearly compounding and 12.75% is continuous compounding.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-5","question":"What is the present value of ₹20,000 received at the end of each year for 5 years at a discount rate of 10%?","options":["₹83,397.31","₹1,00,000.00","₹75,815.74","₹62,092.13"],"answer":2,"explanation":"PV = 20,000 × [1 − 1.1⁻⁵]/0.10 = 20,000 × 3.79079 = ₹75,815.74. Multiplying by 1.1 (₹83,397.31) values an annuity due; discounting the ₹1,00,000 total as one lump sum at year 5 is wrong.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-6","question":"₹5,000 is deposited at the end of every year for 10 years at 8% compounded annually. What is the accumulated amount just after the last deposit?","options":["₹72,432.81","₹78,227.44","₹1,07,946.25","₹62,437.79"],"answer":0,"explanation":"FV of an ordinary annuity = 5,000 × [(1.08¹⁰ − 1)/0.08] = 5,000 × 14.48656 = ₹72,432.81. ₹78,227.44 would be an annuity due; compounding ₹50,000 for the full 10 years ignores that later deposits earn for fewer years.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-7","question":"A share is expected to pay a dividend of ₹4 next year, growing at 5% per year forever. Investors require 13%. What is the share worth today?","options":["₹52.50","₹50.00","₹30.77","₹22.22"],"answer":1,"explanation":"Gordon growth: P₀ = D₁/(r − g) = 4/(0.13 − 0.05) = ₹50. ₹52.50 wrongly grows the already-next-year dividend once more (4 × 1.05/0.08).","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-8","question":"Using the Rule of 72, roughly how many years does money take to double at 9% per annum compounded annually?","options":["11.1 years","6 years","7.2 years","8 years"],"answer":3,"explanation":"Rule of 72: years ≈ 72 / 9 = 8. The exact figure is ln 2 / ln 1.09 ≈ 8.04 years.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-9","question":"A ₹10,00,000 loan at 12% per annum is to be repaid in equal monthly instalments over 5 years (monthly reducing balance). What is the EMI (nearest rupee)?","options":["₹23,117","₹26,667","₹22,244","₹16,667"],"answer":2,"explanation":"r = 1% per month, n = 60. EMI = P·r(1+r)ⁿ/[(1+r)ⁿ − 1] = 10,00,000 × 0.01 × 1.01⁶⁰/(1.01⁶⁰ − 1) ≈ ₹22,244.45. ₹26,667 is a flat-rate EMI (interest on the full principal for 5 years); ₹23,117 is an annual EMI divided by 12.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-10","question":"For the same ₹10,00,000, 12%, 60-month loan (EMI ≈ ₹22,244.45), what principal is still outstanding immediately after the 12th EMI is paid (nearest hundred rupees)?","options":["₹7,33,100","₹8,44,700","₹8,00,000","₹8,53,100"],"answer":1,"explanation":"Outstanding balance = PV of the remaining 48 EMIs at 1% = 22,244.45 × [1 − 1.01⁻⁴⁸]/0.01 ≈ ₹8,44,709.76. Subtracting all 12 EMIs from the principal ignores that most of each early EMI is interest; ₹8,00,000 assumes equal principal repayment.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-11","question":"An investment pays ₹30,000 a year for 4 years, with the first payment at the end of year 4. At 10%, what is its present value?","options":["₹71,447.00","₹64,951.82","₹95,095.96","₹78,591.71"],"answer":0,"explanation":"Value the 4-payment annuity one period before its first payment (end of year 3): 30,000 × 3.16987 = ₹95,095.96. Discount 3 years: ÷ 1.1³ = ₹71,447.00. Discounting 4 years is the common off-by-one error.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-12","question":"A lottery winner may take ₹1,00,000 today or ₹12,000 at the end of every year forever. At an 11% opportunity cost, what should she do?","options":["Take ₹1,00,000 today; it is worth about ₹8,000 more","Indifferent; both are worth ₹1,00,000","Take the perpetuity; it is worth about ₹21,091 more","Take the perpetuity; it is worth about ₹9,091 more"],"answer":3,"explanation":"PV of perpetuity = 12,000/0.11 = ₹1,09,090.91 > ₹1,00,000, so the perpetuity wins by about ₹9,091. ₹21,091 wrongly treats it as a perpetuity due.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-13","question":"Which deposit gives the highest effective annual yield? A: 10% compounded quarterly; B: 10.3% compounded annually; C: 9.9% compounded monthly.","options":["B","A","C","All three are equal"],"answer":1,"explanation":"EAR(A) = 1.025⁴ − 1 = 10.381%; EAR(B) = 10.300%; EAR(C) = (1 + 0.099/12)¹² − 1 = 10.362%. A is highest, though only marginally above C.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-14","question":"An employee wants ₹50,00,000 at the end of 20 years. She will invest a fixed amount at the end of every year earning 9% compounded annually. What is the annual investment (nearest rupee)?","options":["₹89,663","₹2,50,000","₹97,732","₹1,08,652"],"answer":2,"explanation":"Sinking-fund payment = FV × r / [(1+r)ⁿ − 1] = 50,00,000 × 0.09 / (1.09²⁰ − 1) = ₹97,732.38. ₹89,663 is the beginning-of-year (annuity-due) payment; ₹2,50,000 ignores interest, and ₹1,08,652 uses only 19 compounding periods.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-15","question":"A contract pays ₹10,000 at the end of year 1, and each later payment grows by 4%, for 10 payments in total. At 10%, what is its present value?","options":["₹1,66,666.67","₹61,445.67","₹74,412.30","₹71,550.29"],"answer":3,"explanation":"Growing annuity: PV = C/(r − g) × [1 − ((1+g)/(1+r))ⁿ] = 10,000/0.06 × [1 − (1.04/1.10)¹⁰] = ₹71,550.29. ₹1,66,667 treats it as a growing perpetuity; ₹61,445.67 ignores growth.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-16","question":"₹1,00,000 is invested at 8% per annum compounded continuously for 5 years. What is the maturity value?","options":["₹1,49,182.47","₹1,46,932.81","₹1,40,000.00","₹1,48,984.57"],"answer":0,"explanation":"FV = P·e^(rt) = 1,00,000 × e^0.40 = ₹1,49,182.47. Annual compounding gives ₹1,46,932.81 and monthly gives ₹1,48,984.57; continuous is always the highest.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-17","question":"A lender wants an effective annual return of exactly 12%. What nominal annual rate, compounded monthly, should it quote?","options":["12.00%","11.39%","12.68%","11.49%"],"answer":1,"explanation":"(1 + i/12)¹² = 1.12 → i = 12 × (1.12^(1/12) − 1) = 11.387%. 12.68% runs the conversion the wrong way; 11.49% is the quarterly-compounding equivalent.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-18","question":"A perpetuity of ₹5,000 a year makes its first payment at the end of year 5. At 10%, what is it worth today?","options":["₹31,046.07","₹50,000.00","₹34,150.67","₹37,565.74"],"answer":2,"explanation":"C/r = ₹50,000 gives the value at the end of year 4 (one period before the first payment). Discount 4 years: 50,000/1.1⁴ = ₹34,150.67. Discounting 5 years is the usual off-by-one error.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-19","question":"A moneylender charges 2% per month, compounded monthly. What is the effective annual interest rate?","options":["24.00%","26.25%","27.12%","26.82%"],"answer":3,"explanation":"EAR = 1.02¹² − 1 = 26.82%. 24% is the nominal rate; 26.25% would be 24% compounded quarterly and 27.12% continuous compounding.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-20","question":"An instrument pays ₹8,000 at the end of each of the next 3 years and ₹1,00,000 at the end of year 3. At a 10% required return, what is its value?","options":["₹95,026.30","₹93,163.04","₹1,00,000.00","₹80,000.00"],"answer":0,"explanation":"PV = 8,000/1.1 + 8,000/1.1² + 1,08,000/1.1³ = 7,272.73 + 6,611.57 + 81,141.99 = ₹95,026.30. Discounting all ₹1,24,000 at year 3 overstates the delay of the coupons.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-21","question":"Which statement about an annuity due compared with an otherwise identical ordinary annuity is correct?","options":["Both its PV and its FV are higher by a factor of (1 + r)","Its PV is higher by (1 + r) but its FV is the same","Its PV and FV are both lower by a factor of (1 + r)","Its PV is the same but its FV is higher by (1 + r)"],"answer":0,"explanation":"Every payment of an annuity due arrives one period earlier, so each cash flow is worth (1 + r) times more at any valuation date: PV_due = PV_ord × (1 + r) and FV_due = FV_ord × (1 + r).","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-22","question":"A company must redeem ₹20 crore of debentures at the end of 5 years. It will deposit an equal amount at the BEGINNING of each year into a fund earning 7% compounded annually. What is the annual deposit (₹ lakh, 2 decimals)?","options":["₹347.78 lakh","₹325.03 lakh","₹400.00 lakh","₹487.78 lakh"],"answer":1,"explanation":"FV of an annuity due = A × [(1.07⁵ − 1)/0.07] × 1.07 = 20 crore → A = ₹3,25,02,934 ≈ ₹325.03 lakh. ₹347.78 lakh is the end-of-year deposit; ₹487.78 lakh wrongly uses the loan (PV) formula.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-23","question":"How long does money take to triple at 10% per annum compounded annually?","options":["20.00 years","10.99 years","7.20 years","11.53 years"],"answer":3,"explanation":"1.1ⁿ = 3 → n = ln 3 / ln 1.1 = 1.0986/0.09531 = 11.53 years. 20 years is the simple-interest answer and 10.99 years assumes continuous compounding.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-24","question":"A finance company lends ₹1,00,000 repayable in 4 equal year-end instalments of ₹31,547 and advertises a 'flat rate' of interest. What is the true effective annual rate?","options":["6.55%","13.09%","10%","8%"],"answer":2,"explanation":"₹1,00,000/31,547 = 3.1699, which is the 4-year annuity factor at exactly 10%, so the IRR is 10%. The flat rate is (1,26,188 − 1,00,000)/1,00,000/4 = 6.55%, which understates the cost because the principal is repaid gradually.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-25","question":"₹5,000 is received every six months for 3 years (first receipt in 6 months). The discount rate is 10% per annum compounded half-yearly. What is the present value?","options":["₹24,868.52","₹25,378.46","₹21,776.30","₹30,000.00"],"answer":1,"explanation":"Use the per-period rate 5% and 6 periods: 5,000 × [1 − 1.05⁻⁶]/0.05 = 5,000 × 5.07569 = ₹25,378.46. Lumping into ₹10,000 a year at 10% gives ₹24,868.52; using 10% per half-year is wrong.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-26","question":"A deposit pays a nominal 11% per annum while inflation is 6%. What is the exact real rate of return (Fisher relation)?","options":["5.00%","17.66%","4.72%","1.83%"],"answer":2,"explanation":"(1 + nominal) = (1 + real)(1 + inflation) → real = 1.11/1.06 − 1 = 4.72%. 5% is only the approximation (11 − 6).","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-27","question":"A project returns ₹10,000, ₹20,000 and ₹30,000 at the ends of years 1, 2 and 3. At 12%, what is the present value of these inflows?","options":["₹49,847.39","₹42,706.81","₹48,036.63","₹46,225.86"],"answer":3,"explanation":"PV = 10,000/1.12 + 20,000/1.12² + 30,000/1.12³ = 8,928.57 + 15,943.88 + 21,353.41 = ₹46,225.86. ₹49,847.39 reverses the order of the flows; using the average ₹20,000 as an annuity gives ₹48,036.63.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-28","question":"A ₹5,00,000 loan at 10% per annum is repaid in 5 equal year-end instalments. How much of the SECOND instalment is interest?","options":["₹41,810.13","₹50,000.00","₹90,088.61","₹40,000.00"],"answer":0,"explanation":"Instalment = 5,00,000 × 0.10/(1 − 1.1⁻⁵) = ₹1,31,898.74. After year 1 the balance is 5,50,000 − 1,31,898.74 = ₹4,18,101.26; year-2 interest = 10% × that = ₹41,810.13. ₹90,088.61 is the principal part; ₹40,000 assumes equal principal repayments.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-29","question":"Other things equal, which change increases the present value of a fixed future cash flow?","options":["A lower discount rate","A higher discount rate","A longer wait before the cash flow is received","More frequent compounding at the same nominal rate"],"answer":0,"explanation":"PV = FV/(1 + r)ⁿ, so PV rises when r falls. A longer wait or more frequent compounding (higher effective rate) both lower PV.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-30","question":"₹25,000 is put in a deposit paying 6% simple interest per annum. How much interest does it earn in 4 years?","options":["₹6,561.92","₹6,000","₹1,500","₹31,000"],"answer":1,"explanation":"Simple interest = P × r × t = 25,000 × 0.06 × 4 = ₹6,000. ₹6,561.92 is compound interest; ₹31,000 is the amount, not the interest.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-31","question":"A machine costs ₹1,00,000 and generates a constant cash inflow of ₹30,000 a year. What is its simple payback period?","options":["3 years","4 years","3.67 years","3.33 years"],"answer":3,"explanation":"Payback = outlay / annual inflow = 1,00,000 / 30,000 = 3.33 years (3 years and 4 months).","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-32","question":"If a project's net present value at the firm's cost of capital is positive, its profitability index (PI) must be:","options":["Exactly 1","Less than 1 but positive","Greater than 1","Negative"],"answer":2,"explanation":"PI = PV of inflows / outlay = 1 + NPV/outlay, so NPV > 0 ⇔ PI > 1.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-33","question":"A project costs ₹2,00,000 and returns ₹70,000 at the end of each year for 4 years. At a 12% cost of capital, what is its NPV?","options":["₹80,000","₹38,128","₹21,891","₹12,614"],"answer":3,"explanation":"PV of inflows = 70,000 × 3.0373 (4-year annuity factor at 12%) = ₹2,12,614; NPV = ₹2,12,614 − 2,00,000 = ₹12,614. ₹80,000 ignores discounting; ₹38,128 treats the inflows as starting today.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-34","question":"For a project costing ₹2,00,000 with inflows of ₹70,000 a year for 4 years, what is the profitability index at 12%?","options":["1.063","0.063","1.400","0.941"],"answer":0,"explanation":"PI = PV of inflows / outlay = (70,000 × 3.0373)/2,00,000 = 2,12,614/2,00,000 = 1.063. 1.400 uses undiscounted inflows; 0.063 is NPV/outlay, not PI.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-35","question":"A project costing ₹5,60,000 returns ₹1,20,000, ₹1,80,000, ₹2,00,000, ₹1,50,000 and ₹1,00,000 in years 1–5. What is its payback period (cash flows evenly spread within a year)?","options":["3.73 years","3.40 years","4.00 years","3.60 years"],"answer":1,"explanation":"Cumulative inflows: 1.2, 3.0, 5.0 lakh after 3 years. ₹60,000 more is needed out of year 4's ₹1,50,000 → 0.4 year. Payback = 3.40 years. 3.73 years wrongly divides the outlay by the average inflow (₹1,50,000).","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-36","question":"For the same ₹5,60,000 project with inflows of ₹1,20,000, ₹1,80,000, ₹2,00,000, ₹1,50,000 and ₹1,00,000, what is the discounted payback period at 10%?","options":["3.40 years","4.01 years","4.80 years","5.00 years"],"answer":2,"explanation":"Discounted inflows at 10%: 1,09,091, 1,48,760, 1,50,263, 1,02,452, 62,092. Cumulative after 4 years = 5,10,566, short of 5,60,000 by 49,434; year 5 adds 62,092, so discounted payback = 4 + 49,434/62,092 = 4.80 years. 4.01 years wrongly mixes discounted and undiscounted flows.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-37","question":"An investment of ₹1,00,000 returns a single payment of ₹1,44,000 at the end of year 2 and nothing else. What is its IRR?","options":["20%","22%","44%","18.5%"],"answer":0,"explanation":"1,00,000(1 + IRR)² = 1,44,000 → (1 + IRR) = √1.44 = 1.2 → IRR = 20%. 22% is the simple average (44%/2).","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-38","question":"A project's NPV is +₹8,000 at 10% and −₹2,000 at 15%. Using linear interpolation, its IRR is approximately:","options":["11.0%","12.5%","13.0%","14.0%"],"answer":3,"explanation":"IRR ≈ 10% + 5% × 8,000/(8,000 + 2,000) = 10% + 4% = 14%. 11% weights by the wrong NPV (2,000/10,000).","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-39","question":"Mutually exclusive projects, each costing ₹1,00,000: A returns ₹1,30,000 at the end of year 1 (IRR 30%); B returns ₹1,69,000 at the end of year 3 (IRR ≈ 19.1%). The cost of capital is 10%. Which should be chosen?","options":["A, because its IRR is higher","A, because its NPV (₹18,182) is higher","B, because its NPV (₹26,972) exceeds A's (₹18,182)","Either, because both have positive NPV"],"answer":2,"explanation":"NPV(A) = 1,30,000/1.1 − 1,00,000 = ₹18,182; NPV(B) = 1,69,000/1.1³ − 1,00,000 = ₹26,972. For mutually exclusive projects the higher NPV wins; IRR misranks them because of the timing difference.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-40","question":"Projects A (−1,00,000 now, +1,30,000 in year 1) and B (−1,00,000 now, +1,69,000 in year 3) are mutually exclusive. Above what discount rate does A have the higher NPV?","options":["24.56%","14.02%","30.00%","19.11%"],"answer":1,"explanation":"The crossover rate is the IRR of (B − A): −1,30,000 in year 1 and +1,69,000 in year 3 → (1 + r)² = 1.3 → r = 14.02%. Above it the shorter project A wins; below it B wins. Averaging the two IRRs is meaningless.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-41","question":"A project costs ₹1,00,000 and returns ₹50,000 at the end of each of the next 3 years. If inflows are reinvested at the 10% cost of capital, what is its MIRR?","options":["23.38%","18.29%","14.47%","21.83%"],"answer":1,"explanation":"Terminal value of inflows = 50,000(1.1² + 1.1 + 1) = ₹1,65,500. MIRR = (1,65,500/1,00,000)^(1/3) − 1 = 18.29%. The IRR is 23.38%; MIRR is lower because it assumes reinvestment at 10%, not at the IRR.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-42","question":"A project has cash flows of −₹100 now, +₹230 in year 1 and −₹132 in year 2. Which statement is correct?","options":["It has a single IRR of 15%","It has two IRRs, 10% and 20%, and its NPV is positive outside that range","It has two IRRs, 10% and 20%, and its NPV is positive only for discount rates between them","It has no real IRR because the cash flows change sign twice"],"answer":2,"explanation":"Put x = 1 + r: −100x² + 230x − 132 = 0 → x = (230 ± 10)/200 = 1.1 or 1.2, so IRR = 10% and 20%. At 15%, NPV = −100 + 200 − 99.81 = +0.19 > 0, while at 0% NPV = −2, so NPV is positive only between the two IRRs.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-43","question":"A firm spent ₹5 lakh last year on a feasibility study for a new plant. In evaluating the plant today, this ₹5 lakh should be:","options":["Ignored, because it is a sunk cost","Added to the initial outlay","Spread over the plant's life as an annual outflow","Deducted from the project's terminal cash flow"],"answer":0,"explanation":"Capital budgeting uses incremental future cash flows. The study cost has already been incurred whatever the decision, so it is sunk and irrelevant.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-44","question":"A company will build a warehouse on land it bought years ago for ₹20 lakh; the land could be sold today for ₹35 lakh (ignore taxes). How should the land enter the warehouse's NPV analysis?","options":["As a ₹20 lakh outflow at time 0 (historical cost)","It should be ignored because the land is already owned","As a ₹15 lakh inflow (unrealised gain)","As a ₹35 lakh outflow at time 0 (opportunity cost)"],"answer":3,"explanation":"Using the land means giving up ₹35 lakh that could be realised now. Its opportunity cost, not its historical cost, is the relevant cash outflow.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-45","question":"A ₹10,00,000 machine (5-year life, straight-line depreciation, no salvage) raises EBITDA by ₹3,50,000 a year. Tax rate 30%, cost of capital 12%. What is the NPV?","options":["₹99,457","−₹1,16,830","₹2,61,672","−₹6,21,498"],"answer":0,"explanation":"Annual OCF = (EBITDA − depreciation)(1 − t) + depreciation = (3,50,000 − 2,00,000)(0.7) + 2,00,000 = ₹3,05,000. NPV = 3,05,000 × 3.6048 − 10,00,000 = ₹99,457. Ignoring the depreciation tax shield gives −₹1,16,830; ignoring tax gives ₹2,61,672.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-46","question":"For a project year: sales ₹8 lakh, cash operating costs ₹3 lakh, depreciation ₹1 lakh, tax rate 25%. What is the operating cash flow?","options":["₹3.00 lakh","₹4.00 lakh","₹3.75 lakh","₹5.00 lakh"],"answer":1,"explanation":"OCF = (8 − 3 − 1)(1 − 0.25) + 1 = 3.00 + 1.00 = ₹4.00 lakh. Equivalently (8 − 3)(0.75) + 0.25 × 1 = 3.75 + 0.25. ₹3.00 lakh is net profit and ₹3.75 lakh forgets the depreciation tax shield.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-47","question":"At the end of a project, a machine with a tax book value of ₹1.2 lakh is sold for ₹2 lakh; the tax rate is 30% and ₹1.5 lakh of working capital is released. What is the terminal cash flow?","options":["₹3.50 lakh","₹2.90 lakh","₹3.26 lakh","₹1.76 lakh"],"answer":2,"explanation":"After-tax salvage = 2 − 0.30 × (2 − 1.2) = 2 − 0.24 = 1.76 lakh; add working-capital recovery 1.5 lakh → ₹3.26 lakh. ₹3.50 lakh ignores the tax on the gain; ₹2.90 lakh taxes the whole sale price; ₹1.76 lakh forgets working capital.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-48","question":"With ₹10 lakh to invest, a firm can choose among indivisible projects A (cost ₹6 lakh, NPV ₹1.80 lakh), B (₹4 lakh, ₹1.40 lakh), C (₹5 lakh, ₹1.60 lakh) and D (₹3 lakh, ₹0.75 lakh). Which selection maximises NPV?","options":["B and C (total NPV ₹3.00 lakh)","A and D (total NPV ₹2.55 lakh)","B, C and D (total NPV ₹3.75 lakh)","A and B (total NPV ₹3.20 lakh)"],"answer":3,"explanation":"PIs: B 1.35, C 1.32, A 1.30, D 1.25. Ranking by PI picks B + C (₹9 lakh, NPV 3.00) and leaves ₹1 lakh idle, but with indivisible projects the right test is the feasible combination with the highest total NPV: A + B uses all ₹10 lakh for NPV 3.20. B + C + D has a higher NPV but costs ₹12 lakh, beyond the budget.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-49","question":"Two mutually exclusive machines will be replaced repeatedly: X has NPV ₹50,000 over a 3-year life; Y has NPV ₹70,000 over a 5-year life. At 10%, which is better and why?","options":["X, because its equivalent annual annuity (₹20,106) exceeds Y's (₹18,466)","Y, because its NPV is higher","Y, because its equivalent annual annuity (₹18,466) exceeds X's","They are equal once lives are considered"],"answer":0,"explanation":"EAA = NPV / annuity factor: X = 50,000/2.4869 = ₹20,106; Y = 70,000/3.7908 = ₹18,466. For repeated projects of unequal life, compare EAAs, so X wins despite its lower NPV.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-50","question":"Machine P costs ₹3,00,000, runs for 4 years and costs ₹40,000 a year to operate; machine Q costs ₹4,50,000, runs for 6 years and costs ₹25,000 a year. At 12%, compare their equivalent annual costs.","options":["P is cheaper: ₹1,38,770 vs ₹1,34,452 a year","P is cheaper: ₹1,15,000 vs ₹1,00,000 a year","Q is cheaper: ₹1,34,452 vs ₹1,38,770 a year","Both cost the same per year"],"answer":2,"explanation":"EAC = cost / annuity factor + running cost. P: 3,00,000/3.0373 + 40,000 = ₹1,38,770. Q: 4,50,000/4.1114 + 25,000 = ₹1,34,452. Q has the lower EAC. Straight division (₹75,000 + 40,000 vs ₹75,000 + 25,000) ignores the time value of money.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-51","question":"For a conventional project (one outflow followed by inflows), the NPV at 14% is positive. Which conclusions follow? I. The IRR exceeds 14%. II. The PI at 14% exceeds 1. III. The discounted payback at 14% is shorter than the simple payback.","options":["I only","I and II only","I, II and III","II and III only"],"answer":1,"explanation":"With conventional flows NPV falls as the rate rises, so positive NPV at 14% means IRR > 14% (I) and PI > 1 (II). Discounted payback is always LONGER than simple payback, so III is false.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-52","question":"An asset costs ₹5,00,000, has a salvage value of ₹1,00,000 after 5 years and yields an average profit after tax of ₹60,000 a year. What is its accounting rate of return on average investment?","options":["12%","15%","24%","20%"],"answer":3,"explanation":"Average investment = (5,00,000 + 1,00,000)/2 = 3,00,000. ARR = 60,000/3,00,000 = 20%. 12% uses the initial investment; 15% uses the depreciable amount ₹4,00,000.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-53","question":"A project needs ₹8 lakh of machinery plus ₹2 lakh of working capital at the start; the working capital is fully recovered at the end of year 5. Inflows are ₹3 lakh a year for 5 years. At 10%, what is the NPV?","options":["₹2,61,420","₹3,37,236","₹1,37,236","₹2,73,839"],"answer":0,"explanation":"NPV = 3,00,000 × 3.7908 + 2,00,000/1.1⁵ − 10,00,000 = 11,37,236 + 1,24,184 − 10,00,000 = ₹2,61,420. Ignoring working capital altogether gives ₹3,37,236; forgetting its recovery gives ₹1,37,236.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-54","question":"Assertion (A): IRR can rank two mutually exclusive projects differently from NPV. Reason (R): IRR implicitly assumes intermediate cash flows are reinvested at the project's own IRR, whereas NPV assumes reinvestment at the cost of capital.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true. The different reinvestment-rate assumptions (along with differences in scale and timing) are the standard explanation for NPV–IRR ranking conflicts.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-55","question":"A ₹10 lakh project yields ₹2.5 lakh a year for 6 years; the cost of capital is 12%. By what percentage can annual inflows fall before the NPV becomes zero?","options":["2.79%","33.33%","2.71%","12.00%"],"answer":2,"explanation":"PV of inflows = 2,50,000 × 4.1114 = ₹10,27,852; NPV = ₹27,852. Inflows can fall by NPV/PV of inflows = 27,852/10,27,852 = 2.71%. Dividing by the outlay (2.79%) uses the wrong base; 33.33% ignores discounting.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-56","question":"Which statements about payback are correct? I. Simple payback ignores cash flows after the payback date. II. Discounted payback can never be shorter than simple payback for a conventional project. III. A project with a payback shorter than the cut-off must have a positive NPV.","options":["I, II and III","I only","II and III only","I and II only"],"answer":3,"explanation":"I and II are true. III is false: a project can recover its cost quickly yet have little or nothing after payback, so its NPV can still be negative, especially under simple payback.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-57","question":"A project costing ₹1,60,000 is expected to generate ₹1,00,000 a year for 2 years in TODAY'S prices. The nominal cost of capital is 15.5% and inflation is 5%. What is the NPV?","options":["₹1,541","₹13,554","₹12,396","₹40,000"],"answer":1,"explanation":"Real rate = 1.155/1.05 − 1 = 10%. Discount real flows at the real rate: 1,00,000 × 1.7355 − 1,60,000 = ₹13,554. Discounting real flows at the nominal rate (₹1,541) understates NPV; using 15.5 − 5 = 10.5% is only an approximation.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-58","question":"Which capital budgeting method ignores the time value of money?","options":["Net present value","Profitability index","Internal rate of return","Simple payback period"],"answer":3,"explanation":"Simple payback (like ARR) adds undiscounted cash flows. NPV, PI and IRR are discounted cash flow methods.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-59","question":"A diversified firm uses its company-wide WACC of 11% to evaluate all projects. Over time, this practice tends to:","options":["Under-invest in high-risk projects and over-invest in low-risk projects","Have no effect if the WACC is computed with market-value weights","Over-invest in high-risk projects and under-invest in low-risk projects","Lower the firm's beta"],"answer":2,"explanation":"Risky projects deserve a hurdle above 11% and safe ones below it. A single rate accepts risky projects that should be rejected and rejects safe ones that should be accepted, gradually raising the firm's risk.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-60","question":"Match each technique with its feature. Techniques: (p) NPV, (q) IRR, (r) PI, (s) Payback. Features: (1) Best for ranking divisible projects under capital rationing; (2) Measures liquidity rather than profitability; (3) May give multiple answers for non-conventional cash flows; (4) Directly measures the increase in shareholder wealth.","options":["p-1, q-3, r-4, s-2","p-4, q-3, r-1, s-2","p-4, q-1, r-3, s-2","p-3, q-4, r-1, s-2"],"answer":1,"explanation":"NPV is the rupee value added for shareholders (4); IRR can have multiple roots when signs change more than once (3); PI ranks divisible projects when funds are rationed (1); payback is a liquidity/risk screen (2).","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-61","question":"The risk-free rate is 6%, the market return is 12% and a stock's beta is 1.2. What is its required return under CAPM?","options":["14.40%","13.20%","20.40%","7.20%"],"answer":1,"explanation":"Ke = Rf + β(Rm − Rf) = 6% + 1.2 × (12% − 6%) = 6% + 7.2% = 13.2%. 14.4% multiplies beta by the market return instead of the market premium.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-62","question":"A company borrows at 10% and pays tax at 30%. What is its after-tax cost of debt?","options":["10%","13%","3%","7%"],"answer":3,"explanation":"After-tax Kd = 10% × (1 − 0.30) = 7%, because interest is tax-deductible. 3% is the tax saving, not the cost.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-63","question":"A share trades at ₹200. The dividend just paid was ₹10 and dividends are expected to grow at 6% a year forever. What is the cost of equity?","options":["11.00%","5.30%","11.30%","6.00%"],"answer":2,"explanation":"D₁ = 10 × 1.06 = 10.60. Ke = D₁/P₀ + g = 10.60/200 + 6% = 5.3% + 6% = 11.3%. Using D₀ gives 11.0%; 5.3% forgets growth.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-64","question":"A firm has ₹60 lakh of equity (cost 14%) and ₹40 lakh of debt (pre-tax cost 10%). The tax rate is 25%. What is its WACC?","options":["11.40%","12.40%","10.75%","10.10%"],"answer":0,"explanation":"WACC = 0.6 × 14% + 0.4 × 10% × (1 − 0.25) = 8.4% + 3.0% = 11.4%. 12.4% ignores the tax shield; 10.10% swaps the weights.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-65","question":"A company has 10 lakh shares (face value ₹10, market price ₹50) and debentures of face value ₹2 crore trading at 95% of par with a YTM of 9%. The cost of equity is 15% and the tax rate 30%. What is the WACC using market-value weights?","options":["12.60%","9.20%","13.35%","12.51%"],"answer":0,"explanation":"Market values: equity = 10 lakh × ₹50 = ₹5 crore; debt = 0.95 × 2 = ₹1.9 crore. After-tax Kd = 9% × 0.7 = 6.3%. WACC = (5 × 15% + 1.9 × 6.3%)/6.9 = 12.60%. Book weights (₹1 crore and ₹2 crore) give 9.20%; using pre-tax Kd gives 13.35%.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-66","question":"A 5-year bond with face value ₹100 and a 10% annual coupon trades at ₹95. Using the approximation formula, what is its yield to maturity?","options":["10.53%","11.28%","10.00%","11.58%"],"answer":1,"explanation":"Approximate YTM = [coupon + (face − price)/n] / [(face + price)/2] = [10 + 5/5]/97.5 = 11/97.5 = 11.28%. 10.53% is the current yield (10/95), which ignores the ₹5 gain at maturity.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-67","question":"Irredeemable 12% preference shares of face value ₹100 are issued at ₹95, with flotation costs of 2% of face value. What is the cost of preference capital?","options":["12.00%","12.63%","12.90%","9.03%"],"answer":2,"explanation":"Net proceeds = 95 − 2 = ₹93. Kp = 12/93 = 12.90%. Preference dividends are not tax-deductible, so no (1 − t) adjustment; 9.03% wrongly applies one.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-68","question":"A firm's share price is ₹100, next year's dividend is ₹5 and growth is 7%. New shares involve flotation costs of 5% of the price. What are the costs of retained earnings and of new equity?","options":["12.26% and 12.00%","12.00% and 12.00%","12.35% and 12.26%","12.00% and 12.26%"],"answer":3,"explanation":"Retained earnings: Ke = 5/100 + 7% = 12%. New equity: Ke = 5/(100 × 0.95) + 7% = 5.263% + 7% = 12.26%. New equity costs more because of flotation costs.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-69","question":"A comparable listed firm has an equity beta of 1.5 at a debt–equity ratio of 0.5. Your firm has the same business risk but a debt–equity ratio of 1.0. Tax rate 30%, risk-free rate 6%, market risk premium 7%. What is your firm's cost of equity?","options":["19.22%","16.50%","20.00%","23.85%"],"answer":0,"explanation":"Unlever: β_U = 1.5/[1 + 0.7 × 0.5] = 1.1111. Relever: β_L = 1.1111 × [1 + 0.7 × 1.0] = 1.8889. Ke = 6% + 1.8889 × 7% = 19.22%. 16.5% uses the comparable's beta unchanged; 20% ignores taxes in unlevering and relevering (β_U = 1.0, β_L = 2.0); 23.85% relevers the comparable beta without unlevering it first.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-70","question":"A firm targets 30% debt and 70% equity. Its beta is 1.3, the risk-free rate 7%, the market risk premium 6%, its pre-tax cost of debt 10% and its tax rate 25%. What is its WACC?","options":["13.36%","12.61%","11.01%","14.80%"],"answer":1,"explanation":"Ke = 7% + 1.3 × 6% = 14.8%. After-tax Kd = 10% × 0.75 = 7.5%. WACC = 0.7 × 14.8% + 0.3 × 7.5% = 10.36% + 2.25% = 12.61%. 13.36% ignores the tax shield; 14.8% is just the cost of equity.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-71","question":"A firm sells 10,000 units at ₹50 each; variable cost is ₹30 per unit and fixed operating costs are ₹1,20,000. What is its degree of operating leverage?","options":["1.67","0.40","2.50","1.60"],"answer":2,"explanation":"Contribution = 10,000 × (50 − 30) = ₹2,00,000; EBIT = 2,00,000 − 1,20,000 = ₹80,000. DOL = contribution/EBIT = 2,00,000/80,000 = 2.5. 0.40 is the inverse (EBIT/contribution).","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-72","question":"A firm has contribution of ₹2,00,000, EBIT of ₹80,000 and interest of ₹20,000. What is its degree of combined leverage?","options":["3.83","1.88","2.50","3.33"],"answer":3,"explanation":"DOL = 2,00,000/80,000 = 2.5; DFL = 80,000/(80,000 − 20,000) = 1.333; DCL = 2.5 × 1.333 = 3.33 (= contribution/EBT = 2,00,000/60,000). Adding the two (3.83) is the trap.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-73","question":"A company's DOL is 2.5 and its DFL is 1.6. If sales rise by 8%, by how much will EPS rise?","options":["32.0%","20.0%","12.8%","33.6%"],"answer":0,"explanation":"DCL = 2.5 × 1.6 = 4.0, so %ΔEPS = 4.0 × 8% = 32%. 20% applies only DOL (EBIT change); 33.6% wrongly adds (2.5 + 1.6) × 8%.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-74","question":"Selling price ₹50, variable cost ₹30 per unit, fixed costs ₹1,20,000 and current sales of 10,000 units. What is the margin of safety, and how does it relate to DOL?","options":["60%, which equals 1/DOL","40%, which equals 1/DOL","40%, which equals DOL − 1","60%, which equals 1 − 1/DOL"],"answer":1,"explanation":"Break-even = 1,20,000/20 = 6,000 units. Margin of safety = (10,000 − 6,000)/10,000 = 40%. DOL = 2.5 and 1/2.5 = 0.40: the margin of safety ratio is always the reciprocal of DOL.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-75","question":"EBIT is ₹5 lakh, interest ₹1 lakh and preference dividend ₹60,000; the tax rate is 40%. What is the degree of financial leverage?","options":["1.250","1.471","1.374","1.667"],"answer":3,"explanation":"Preference dividend is paid from after-tax profit, so gross it up: 60,000/(1 − 0.4) = ₹1,00,000. DFL = EBIT/[EBIT − I − Dp/(1 − t)] = 5/(5 − 1 − 1) = 1.667. 1.250 ignores the preference dividend; 1.471 forgets the gross-up.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-76","question":"A new company needs ₹50 lakh. Plan 1: issue 5 lakh equity shares of ₹10. Plan 2: issue 2.5 lakh shares of ₹10 and ₹25 lakh of 12% debt. Tax rate 30%. At what EBIT are the two plans' EPS equal, and what is that EPS?","options":["EBIT ₹3 lakh; EPS ₹0.42","EBIT ₹12 lakh; EPS ₹1.68","EBIT ₹6 lakh; EPS ₹0.84","EBIT ₹6 lakh; EPS ₹1.20"],"answer":2,"explanation":"(EBIT)(0.7)/5 = (EBIT − 3)(0.7)/2.5 (₹ lakh, shares in lakh) → 2.5 EBIT = 5 EBIT − 15 → EBIT = ₹6 lakh. EPS = 6 × 0.7/5 = ₹0.84 under both plans. ₹1.20 forgets tax.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-77","question":"Plan 1: 10 lakh equity shares. Plan 2: 6 lakh equity shares plus ₹40 lakh of 10% preference shares. Tax rate 40%. What is the EBIT indifference point?","options":["₹10.00 lakh","₹6.67 lakh","₹25.00 lakh","₹16.67 lakh"],"answer":3,"explanation":"0.6 EBIT/10 = (0.6 EBIT − 4)/6 (₹ lakh) → 3.6 EBIT = 6 EBIT − 40 → EBIT = 40/2.4 = ₹16.67 lakh. Treating the ₹4 lakh preference dividend as if it were pre-tax interest gives ₹10 lakh.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-78","question":"Under Modigliani–Miller without taxes, an all-equity firm has a cost of capital of 12%. An identical firm is financed 40% by debt costing 8% and 60% by equity. What is the levered firm's cost of equity?","options":["12.00%","14.67%","13.60%","10.40%"],"answer":1,"explanation":"MM Proposition II: Ke = Ko + (Ko − Kd) × D/E = 12% + (12% − 8%) × 40/60 = 14.67%. 13.6% uses D/V (0.4) instead of D/E; 10.4% is the WACC-style average 0.6 × 12 + 0.4 × 8.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-79","question":"Under Modigliani–Miller with corporate taxes, an unlevered firm is worth ₹200 crore. An identical firm has ₹80 crore of permanent debt; the tax rate is 25%. What is the value of the levered firm's equity?","options":["₹140 crore","₹120 crore","₹220 crore","₹200 crore"],"answer":0,"explanation":"V_L = V_U + tD = 200 + 0.25 × 80 = ₹220 crore; equity = V_L − D = 220 − 80 = ₹140 crore. ₹220 crore is the firm value, not equity; ₹120 crore ignores the tax shield.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-80","question":"Which statements are correct? I. Under the Net Income approach, using more debt raises firm value. II. Under the Net Operating Income approach, the overall cost of capital is constant whatever the leverage. III. Under the traditional approach, there is an optimal capital structure.","options":["I and II only","II and III only","I, II and III","I and III only"],"answer":2,"explanation":"NI approach: Ke and Kd are constant, so adding cheaper debt lowers WACC and raises value. NOI approach: Ko is constant and Ke rises to offset cheaper debt. Traditional approach: WACC first falls, then rises, so an optimum exists.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-81","question":"Assertion (A): Retained earnings are not a free source of finance. Reason (R): Shareholders forgo the return they could have earned by investing the dividends themselves.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: retained earnings carry an opportunity cost roughly equal to the cost of equity (without flotation costs).","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-82","question":"A firm estimates these after-tax costs: at 0% debt, Ke = 12%; at 20% debt, Ke = 12.5% and Kd = 7%; at 40% debt, Ke = 14% and Kd = 8%; at 60% debt, Ke = 18% and Kd = 10%. Under the traditional view, which debt ratio is optimal?","options":["0% debt (WACC 12.0%)","40% debt (WACC 11.6%)","20% debt (WACC 11.4%)","60% debt (WACC 13.2%)"],"answer":2,"explanation":"WACC: 0% → 12%; 20% → 0.8 × 12.5 + 0.2 × 7 = 11.4%; 40% → 0.6 × 14 + 0.4 × 8 = 11.6%; 60% → 0.4 × 18 + 0.6 × 10 = 13.2%. The minimum WACC (11.4%) is at 20% debt.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-83","question":"A firm earns an operating return on assets (EBIT/assets) of 15%. It borrows at 10%, has a debt–equity ratio of 1 and pays tax at 30%. What is its return on equity?","options":["10.5%","20.0%","17.5%","14.0%"],"answer":3,"explanation":"ROE = [ROA + (ROA − Kd) × D/E](1 − t) = [15% + 5% × 1] × 0.7 = 14%. The unlevered ROE would be 15% × 0.7 = 10.5%; 20% forgets tax. Leverage helps because ROA > Kd.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-84","question":"Why is debt usually the cheapest source of long-term finance for a profitable company?","options":["Debt never has to be repaid","Interest is tax-deductible and lenders bear less risk than shareholders","Lenders share in the company's profits","Debt does not increase financial risk"],"answer":1,"explanation":"Lenders have a fixed, prior claim, so they accept a lower return, and the tax deductibility of interest cuts the effective cost further. Debt does raise financial risk and must be repaid.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-85","question":"A firm's DOL is 3 and its DFL is 2; its current EPS is ₹12. If sales fall by 5%, what will EPS become?","options":["₹9.00","₹10.80","₹11.40","₹8.40"],"answer":3,"explanation":"DCL = 3 × 2 = 6, so EPS falls 6 × 5% = 30%: 12 × 0.70 = ₹8.40. Adding the leverages (5 × 5% = 25%) gives ₹9.00; using only DFL gives ₹10.80.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-86","question":"A company's degree of financial leverage is 1.25 and it has no preference shares. What is its interest coverage ratio (EBIT/interest)?","options":["5 times","1.25 times","4 times","0.8 times"],"answer":0,"explanation":"DFL = EBIT/(EBIT − I) = 1.25 → EBIT = 1.25 EBIT − 1.25 I → 0.25 EBIT = 1.25 I → EBIT/I = 5.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-87","question":"Irredeemable 12% debentures of face value ₹100 are issued at ₹96 net of costs. The tax rate is 30%. What is the after-tax cost of debt?","options":["8.40%","8.75%","12.50%","12.00%"],"answer":1,"explanation":"Kd = I(1 − t)/net proceeds = 12 × 0.7/96 = 8.4/96 = 8.75%. 8.40% uses face value instead of net proceeds; 12.50% is the pre-tax cost.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-88","question":"A firm keeps 60% equity and 40% debt and expects ₹30 lakh of retained earnings this year. Beyond what total capital budget must it issue costlier new equity (the retained-earnings break point)?","options":["₹30 lakh","₹18 lakh","₹50 lakh","₹75 lakh"],"answer":2,"explanation":"Break point = retained earnings / equity weight = 30/0.6 = ₹50 lakh. Up to ₹50 lakh, the equity part (60%) is met from retained earnings; beyond it new shares are needed. ₹75 lakh divides by the debt weight.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-89","question":"A firm sells at ₹50 a unit with variable cost ₹30 and fixed costs ₹1,20,000. If volume falls from 10,000 to 8,000 units, what happens to EBIT and to DOL?","options":["EBIT falls 20% to ₹64,000 and DOL stays 2.5","EBIT falls 50% to ₹40,000 and DOL falls to 1.6","EBIT falls 40% to ₹48,000 and DOL rises to 3.3","EBIT falls 50% to ₹40,000 and DOL rises to 4.0"],"answer":3,"explanation":"At 10,000 units EBIT = ₹80,000 and DOL = 2.5, so a 20% volume fall cuts EBIT by 2.5 × 20% = 50% to ₹40,000 (check: 8,000 × 20 − 1,20,000). New DOL = 1,60,000/40,000 = 4.0: leverage rises as sales approach break-even.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-90","question":"Which theory holds that, in perfect markets without taxes, a firm's value does not depend on how it is financed?","options":["Net Income approach","Pecking order theory","Modigliani–Miller proposition I","Traditional approach"],"answer":2,"explanation":"MM (1958) showed that without taxes, bankruptcy costs or information asymmetry, firm value depends only on its assets' cash flows and risk, not on the debt–equity mix.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-91","question":"A firm holds inventory for 60 days, collects receivables in 45 days and pays suppliers in 30 days. What is its cash conversion cycle?","options":["75 days","135 days","105 days","15 days"],"answer":0,"explanation":"Operating cycle = 60 + 45 = 105 days; cash conversion cycle = 105 − 30 = 75 days. 135 days wrongly adds the payable period.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-92","question":"Cost of goods sold ₹36.5 lakh, average inventory ₹6 lakh, credit sales ₹73 lakh, average debtors ₹9 lakh, credit purchases ₹40.15 lakh and average creditors ₹3.3 lakh (365-day year). What is the cash conversion cycle?","options":["105 days","75 days","135 days","45 days"],"answer":1,"explanation":"Inventory days = 6/36.5 × 365 = 60; receivable days = 9/73 × 365 = 45; payable days = 3.3/40.15 × 365 = 30. CCC = 60 + 45 − 30 = 75 days. Computing inventory days on sales instead of COGS gives 30 days and a CCC of 45.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-93","question":"Annual demand is 10,000 units, the cost of placing an order is ₹200 and the holding cost is ₹4 per unit per year. What is the economic order quantity?","options":["707 units","1,000 units","1,414 units","500 units"],"answer":1,"explanation":"EOQ = √(2AO/C) = √(2 × 10,000 × 200/4) = √10,00,000 = 1,000 units. 707 units forgets the 2 in the formula.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-94","question":"With annual demand of 10,000 units, ordering cost ₹200 and holding cost ₹4 per unit per year, what is the total annual ordering-plus-holding cost at the EOQ?","options":["₹2,000","₹6,000","₹4,828","₹4,000"],"answer":3,"explanation":"EOQ = 1,000 units. Ordering cost = (10,000/1,000) × 200 = ₹2,000; holding cost = (1,000/2) × 4 = ₹2,000; total ₹4,000. At EOQ the two costs are always equal.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-95","question":"A retailer sells 24,000 units a year. Each order costs ₹150 to place, the unit price is ₹50 and annual carrying cost is 12% of the price. What is the EOQ (nearest unit)?","options":["316 units","379 units","1,095 units","775 units"],"answer":2,"explanation":"Holding cost C = 12% × 50 = ₹6 per unit per year. EOQ = √(2 × 24,000 × 150/6) = √12,00,000 = 1,095.4 ≈ 1,095 units. Using monthly demand gives 316; using the price ₹50 as C gives 379.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-96","question":"Annual demand 10,000 units, price ₹10, ordering cost ₹200 per order, holding cost 20% of price a year. The supplier offers a 2% discount on orders of at least 2,500 units. Should the firm take the discount, and what is the annual saving?","options":["Yes; total cost falls by about ₹1,578","No; total cost rises by about ₹650","Yes; total cost falls by exactly ₹2,000","No; EOQ (1,414 units) is always optimal"],"answer":0,"explanation":"At EOQ = √(2 × 10,000 × 200/2) = 1,414: purchase ₹1,00,000 + ordering 1,414 + holding 1,414 = ₹1,02,828. At 2,500 units (price ₹9.80, C = ₹1.96): 98,000 + 4 × 200 + 1,250 × 1.96 = ₹1,01,250. Saving ≈ ₹1,578. ₹2,000 counts only the price discount and ignores the higher holding cost.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-97","question":"Daily usage is 40 units, the supplier's lead time is 12 days and the firm keeps a safety stock of 200 units. What is the reorder level?","options":["680 units","480 units","880 units","240 units"],"answer":0,"explanation":"Reorder level = lead-time demand + safety stock = 40 × 12 + 200 = 680 units. 480 units forgets the safety stock.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-98","question":"A supplier offers terms of 2/10 net 40. What is the approximate annualised cost of NOT taking the discount and paying on day 40 (365-day year, simple basis)?","options":["24.33%","18.62%","24.83%","2.04%"],"answer":2,"explanation":"Cost = [d/(100 − d)] × [365/(credit period − discount period)] = (2/98) × (365/30) = 24.83%. Using 2/100 gives 24.33%; dividing by 40 instead of 30 days ignores that the discount is available until day 10.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-99","question":"Credit sales are ₹50 lakh with 30-day terms. Extending terms to 60 days would raise sales by 10%. Contribution margin is 25%, bad debts on the extra sales would be 4%, and funds tied up in receivables (valued at sales value, 360-day year) cost 12%. What is the net effect on annual profit?","options":["Gain of ₹95,000","Gain of ₹1,05,000","Loss of ₹15,000","Gain of ₹45,000"],"answer":3,"explanation":"Extra contribution = 5 lakh × 25% = ₹1,25,000. Extra bad debts = 4% × 5 lakh = ₹20,000. Receivables rise from 50 × 30/360 = 4.17 lakh to 55 × 60/360 = 9.17 lakh, i.e. by ₹5 lakh; cost = 12% × 5 lakh = ₹60,000. Net gain = 1,25,000 − 20,000 − 60,000 = ₹45,000. ₹95,000 counts the funding cost only on the new sales.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-100","question":"Annual credit sales are ₹60 lakh on 1-month terms; variable costs are 70% of sales and fixed costs will not change. Offering 2-month terms would lift sales to ₹72 lakh, while bad debts rise from 1% to 2% of total sales. The required return on receivables, valued at variable cost, is 15%. What is the net gain from the new policy?","options":["₹1.710 lakh","₹2.025 lakh","₹2.760 lakh","₹2.625 lakh"],"answer":1,"explanation":"Extra contribution = 12 × 30% = 3.60 lakh. Bad debts: 1.44 − 0.60 = 0.84 lakh. Receivables at variable cost: old 60 × 0.7/12 = 3.5 lakh, new 72 × 0.7 × 2/12 = 8.4 lakh; extra 4.9 lakh × 15% = 0.735 lakh. Net = 3.60 − 0.84 − 0.735 = ₹2.025 lakh. Valuing receivables at sales value gives 1.71; ignoring the cost of funds gives 2.76.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-101","question":"Which statement about working-capital financing policies is correct?","options":["A conservative policy finances temporary current assets with short-term funds only","The matching (hedging) policy finances fixed assets with short-term funds","An aggressive policy finances part of the permanent current assets with short-term funds, raising return and refinancing risk","An aggressive policy lowers both expected return and risk"],"answer":2,"explanation":"Matching: permanent needs from long-term funds, temporary needs from short-term funds. Aggressive: some permanent needs from cheaper short-term funds (higher return, higher risk). Conservative: even part of the temporary needs from long-term funds.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-102","question":"Current assets are ₹12 lakh and current liabilities ₹8 lakh. The firm pays ₹2 lakh to creditors in cash. What happens to the current ratio and net working capital?","options":["Current ratio falls from 1.50 to 1.25; NWC falls to ₹2 lakh","Current ratio stays 1.50; NWC stays ₹4 lakh","Current ratio rises from 1.50 to 1.67; NWC rises to ₹6 lakh","Current ratio rises from 1.50 to 1.67; NWC stays ₹4 lakh"],"answer":3,"explanation":"Both sides fall by ₹2 lakh: CA = 10, CL = 6. Current ratio = 10/6 = 1.67 (up from 1.50, because it was above 1). NWC = 10 − 6 = ₹4 lakh, unchanged.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-103","question":"Current assets of ₹12 lakh include inventory of ₹5 lakh and prepaid expenses of ₹1 lakh. Current liabilities are ₹6 lakh. What is the quick (acid-test) ratio?","options":["1.17","1.00","2.00","0.83"],"answer":1,"explanation":"Quick assets = 12 − 5 − 1 = ₹6 lakh; quick ratio = 6/6 = 1.00. 1.17 forgets to exclude prepaid expenses; 2.00 is the current ratio.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-104","question":"Under the Baumol model, a firm needs ₹36 lakh of cash a year, each conversion of securities into cash costs ₹150, and securities earn 9% a year. What is the optimal cash withdrawal size (nearest rupee)?","options":["₹1,09,545","₹77,460","₹31,623","₹10,954"],"answer":0,"explanation":"C* = √(2 × T × b / i) = √(2 × 36,00,000 × 150/0.09) = √(1.2 × 10¹⁰) ≈ ₹1,09,545. Forgetting the 2 gives ₹77,460; using monthly need gives ₹31,623.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-105","question":"Cost of goods sold is ₹48 lakh, opening inventory ₹7 lakh and closing inventory ₹9 lakh. What is the inventory turnover ratio?","options":["5.33 times","6.86 times","8.00 times","6.00 times"],"answer":3,"explanation":"Average inventory = (7 + 9)/2 = ₹8 lakh. Turnover = 48/8 = 6 times (about 61 days). Using closing inventory gives 5.33; using opening gives 6.86.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-106","question":"A company with annual credit sales of ₹7.3 crore cuts its average collection period from 60 to 45 days (365-day year). If its cost of funds is 10%, what is the annual interest saving?","options":["₹30 lakh","₹3 lakh","₹1.5 lakh","₹9 lakh"],"answer":1,"explanation":"Daily sales = 7.3 crore/365 = ₹2 lakh. Receivables fall by 15 days × 2 lakh = ₹30 lakh, which saves 10% × 30 lakh = ₹3 lakh a year. ₹30 lakh is the cash released, not the saving.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-107","question":"In factoring WITHOUT recourse, who bears the loss if a customer fails to pay a factored invoice?","options":["The selling firm","The customer's bank","The factor","The loss is shared equally by law"],"answer":2,"explanation":"Without recourse the factor buys the credit risk, so it bears bad debts and charges a higher fee. With recourse, the seller must make good any default.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-108","question":"Net working capital is defined as:","options":["Current assets minus current liabilities","Total current assets","Current assets minus inventory","Fixed assets minus long-term debt"],"answer":0,"explanation":"Gross working capital is total current assets; net working capital is current assets less current liabilities.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-109","question":"Using Walter's model: EPS ₹10, DPS ₹4, return on investment 15% and cost of equity 12%. What is the share price?","options":["₹95.83","₹83.33","₹33.33","₹104.17"],"answer":0,"explanation":"P = [D + (r/k)(E − D)]/k = [4 + (0.15/0.12) × 6]/0.12 = (4 + 7.5)/0.12 = ₹95.83. ₹83.33 is E/k (the price when r = k); ₹104.17 is the price at zero payout.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-110","question":"Under Walter's model, a firm earns 15% on reinvested funds while its shareholders require 12%. What payout maximises the share price?","options":["100% (distribute all earnings)","The payout makes no difference","Exactly 50%","0% (retain all earnings)"],"answer":3,"explanation":"When r > k, every rupee retained creates more value than it would in shareholders' hands, so Walter's price is maximised at zero payout. When r < k the optimum is 100%; when r = k payout is irrelevant.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-111","question":"Under Gordon's model, a firm has EPS ₹20, earns 15% on retained funds and has a cost of equity of 12%. If it cuts its retention ratio from 60% to 40%, what happens to the share price?","options":["It rises from ₹266.67 to ₹200.00","It rises from ₹200.00 to ₹266.67","It falls from ₹266.67 to ₹200.00","It stays at ₹166.67"],"answer":2,"explanation":"g = b × r. At b = 0.6: g = 9%, D = 8, P = 8/(0.12 − 0.09) = ₹266.67. At b = 0.4: g = 6%, D = 12, P = 12/(0.12 − 0.06) = ₹200.00. With r > k, retaining less lowers growth and the price.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-112","question":"Under MM dividend irrelevance, a share trades at ₹100 today and investors require 10%. If a dividend of ₹5 is paid at year-end, what will the ex-dividend price at year-end be?","options":["₹110","₹105","₹100","₹95"],"answer":1,"explanation":"P₀ = (D₁ + P₁)/(1 + k) → 100 = (5 + P₁)/1.10 → P₁ = 110 − 5 = ₹105. Without the dividend P₁ would be ₹110; shareholders' total wealth is the same either way.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-113","question":"Under MM, a firm has 1 lakh shares priced at ₹100, cost of equity 10%, expected net income ₹20 lakh and planned investment ₹30 lakh. It will pay a ₹5 dividend at year-end. How many new shares must it issue at year-end to finance the investment?","options":["15,000","9,091","14,286","10,000"],"answer":2,"explanation":"Year-end price P₁ = 100 × 1.10 − 5 = ₹105. Funds needed = 30 − (20 − 5) = ₹15 lakh. New shares = 15,00,000/105 = 14,286. 15,000 uses the old price; 9,091 is the answer if no dividend were paid (₹10 lakh at ₹110).","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-114","question":"Which statements are correct? I. A bonus issue leaves total shareholders' funds unchanged. II. A stock split changes the face value per share. III. A bonus issue reduces the company's cash.","options":["I and II only","I, II and III","I only","II and III only"],"answer":0,"explanation":"A bonus issue capitalises reserves into share capital, so total net worth and cash are unchanged (III is false). A split divides each share into more shares of lower face value.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-115","question":"Under Lintner's model, a firm has a target payout of 40% and an adjustment factor of 0.5. Last year's DPS was ₹4 and this year's EPS is ₹15. What DPS should it declare?","options":["₹6.00","₹4.50","₹7.00","₹5.00"],"answer":3,"explanation":"D₁ = D₀ + speed × (target payout × EPS − D₀) = 4 + 0.5 × (0.4 × 15 − 4) = 4 + 0.5 × 2 = ₹5. ₹6 is the full target dividend with no smoothing.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-116","question":"A company's EPS is ₹8, its DPS is ₹3 and its share price is ₹60. What are its payout ratio and dividend yield?","options":["62.5% and 5.0%","37.5% and 5.0%","37.5% and 13.3%","5.0% and 37.5%"],"answer":1,"explanation":"Payout = DPS/EPS = 3/8 = 37.5%. Dividend yield = DPS/price = 3/60 = 5%. 62.5% is the retention ratio; 13.3% is the earnings yield.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-117","question":"The 'bird-in-hand' argument, that investors value a certain dividend today more than uncertain future capital gains, is most associated with:","options":["Modigliani and Miller","James Walter","Myron Gordon","Harry Markowitz"],"answer":2,"explanation":"Gordon (with Lintner) argued that risk-averse investors prefer current dividends, so higher payout lowers the required return. MM argued dividends are irrelevant.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-118","question":"A company earns ₹50 lakh after tax on 10 lakh shares. It buys back 1 lakh shares at ₹60 using cash that was earning 6% pre-tax; the tax rate is 25%. What is EPS after the buyback?","options":["₹5.26","₹5.00","₹5.56","₹5.16"],"answer":0,"explanation":"Lost after-tax income = 60 lakh × 6% × 0.75 = ₹2.7 lakh. New EPS = (50 − 2.7) lakh/9 lakh = ₹5.26 (up from ₹5.00). ₹5.56 ignores the lost interest; ₹5.16 forgets that the interest was taxable.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-119","question":"Assertion (A): Under Walter's model, if a firm's return on investment equals its cost of equity, the dividend payout has no effect on the share price. Reason (R): Each rupee retained then earns exactly what shareholders could earn by reinvesting it themselves.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"With r = k, P = [D + (E − D)]/k = E/k whatever D is. R gives the economic reason, so R explains A.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-120","question":"A firm follows a residual dividend policy with a target capital structure of 40% debt and 60% equity. Net income is ₹80 lakh and planned capital spending is ₹60 lakh. What dividend will it pay?","options":["₹20 lakh","₹44 lakh","₹56 lakh","₹32 lakh"],"answer":1,"explanation":"Equity needed for the budget = 60% × 60 = ₹36 lakh, taken from earnings first. Residual dividend = 80 − 36 = ₹44 lakh. ₹20 lakh wrongly funds the whole budget from equity; ₹56 lakh uses the debt share.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-121","question":"A 3-year bond of face value ₹1,000 pays an 8% annual coupon. If the market yield is 10%, what is its price?","options":["₹1,000.00","₹1,051.54","₹751.31","₹950.26"],"answer":3,"explanation":"Price = 80 × [1 − 1.1⁻³]/0.10 + 1,000/1.1³ = 80 × 2.4869 + 751.31 = ₹950.26. Because the coupon (8%) is below the yield (10%), the bond sells at a discount. ₹751.31 values only the principal.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-122","question":"A 2-year bond of face value ₹1,000 pays a 10% coupon half-yearly. The market yield is 8% per annum compounded half-yearly. What is its price?","options":["₹1,035.67","₹900.64","₹1,000.00","₹1,036.30"],"answer":3,"explanation":"Per half-year: coupon ₹50, yield 4%, 4 periods. Price = 50 × 3.6299 + 1,000/1.04⁴ = 181.49 + 854.80 = ₹1,036.30. Annual discounting gives ₹1,035.67; using 8% per half-year gives ₹900.64.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-123","question":"When a bond's yield to maturity is higher than its coupon rate, the bond trades:","options":["Above face value (at a premium)","Exactly at face value","Below face value (at a discount)","At a price that cannot be determined from this information"],"answer":2,"explanation":"A buyer needs a return above the coupon, which comes from paying less than face value and gaining the difference at maturity.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-124","question":"A bond with face value ₹1,000 and a 9% annual coupon trades at ₹900. What is its current yield?","options":["9.00%","10.00%","8.10%","11.11%"],"answer":1,"explanation":"Current yield = annual coupon/price = 90/900 = 10%. 9% is the coupon rate on face value; current yield ignores the gain at maturity, so YTM would be higher still.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-125","question":"A 5-year zero-coupon bond has a face value of ₹1,00,000. If investors require 7% a year (annual compounding), what is its price?","options":["₹65,000.00","₹74,074.07","₹71,298.62","₹76,289.52"],"answer":2,"explanation":"Price = 1,00,000/1.07⁵ = 1,00,000/1.40255 = ₹71,298.62. ₹65,000 deducts simple interest; 1.35 in the denominator is simple-interest discounting.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-126","question":"A 2-year bond pays a 10% annual coupon on ₹1,000 face value and yields 10%. What is its modified duration?","options":["1.9091 years","1.7355 years","2.0000 years","2.1000 years"],"answer":1,"explanation":"PV of cash flows: 100/1.1 = 90.91 and 1,100/1.21 = 909.09 (price ₹1,000). Macaulay duration = (1 × 90.91 + 2 × 909.09)/1,000 = 1.9091 years. Modified = 1.9091/1.10 = 1.7355. 2 years is the maturity, which equals duration only for a zero-coupon bond.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-127","question":"A bond priced at ₹1,040 has a modified duration of 6.5. If yields rise by 50 basis points, what is the approximate new price (ignoring convexity)?","options":["₹1,006.20","₹1,073.80","₹972.40","₹1,036.75"],"answer":0,"explanation":"%ΔP ≈ −D_mod × Δy = −6.5 × 0.005 = −3.25%. New price ≈ 1,040 × 0.9675 = ₹1,006.20. A rise in yields lowers the price; ₹972.40 uses a 1% move.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-128","question":"A 3-year zero-coupon bond with face value ₹10,000 sells for ₹7,938.32. What is its yield to maturity?","options":["8.66%","25.97%","7.70%","8.00%"],"answer":3,"explanation":"(10,000/7,938.32)^(1/3) − 1 = 1.25971^(1/3) − 1 = 8.00%. 8.66% is the simple annual average (25.97%/3); 25.97% is the total 3-year return.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-129","question":"A 5-year, 6% annual-coupon bond (face ₹1,000) is bought at ₹920.15 to yield 8%. If its yield is still 8% one year later, what is the one-year holding-period return?","options":["6.00%","8.00%","6.52%","1.48%"],"answer":1,"explanation":"Next year's price (4 years left at 8%) = ₹933.76. HPR = [60 + (933.76 − 920.15)]/920.15 = 8.00%. With an unchanged yield, a bond's one-year return equals its YTM: the current yield (6.52%) plus the pull towards par (1.48%).","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-130","question":"A convertible bond can be exchanged for 25 shares now trading at ₹44 each. Its straight-bond value is ₹980. What is the minimum price at which it should trade?","options":["₹980","₹1,040","₹2,080","₹1,100"],"answer":3,"explanation":"Conversion value = 25 × 44 = ₹1,100. A convertible is worth at least the higher of its straight value (₹980) and conversion value (₹1,100), otherwise arbitrageurs would buy and convert.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-131","question":"A company has just paid a dividend of ₹3. Dividends will grow at 8% a year forever and investors require 14%. What is the share's intrinsic value?","options":["₹54.00","₹50.00","₹23.14","₹58.32"],"answer":0,"explanation":"D₁ = 3 × 1.08 = 3.24. P₀ = D₁/(k − g) = 3.24/0.06 = ₹54. ₹50 uses D₀; ₹58.32 grows the dividend one year too many.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-132","question":"A firm has just paid ₹2 a share. Dividends will grow 20% a year for the next 2 years and 5% a year after that. With a 12% required return, what is the share worth today?","options":["₹35.19","₹37.24","₹38.88","₹30.00"],"answer":2,"explanation":"D₁ = 2.40, D₂ = 2.88, D₃ = 2.88 × 1.05 = 3.024. P₂ = D₃/(k − g) = 3.024/0.07 = 43.20. P₀ = 2.40/1.12 + (2.88 + 43.20)/1.12² = 2.143 + 36.735 = ₹38.88. Discounting P₂ three years is the classic timing error; using D₂ instead of D₃ in P₂ gives ₹37.24.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-133","question":"A company pays out 40% of earnings, grows at 7% a year forever and has a 12% cost of equity. What is its justified P/E on NEXT year's earnings?","options":["8.56","3.33","8.00","20.00"],"answer":2,"explanation":"P₀ = D₁/(k − g) = 0.4 E₁/0.05 → P₀/E₁ = 0.4/0.05 = 8.0. On trailing earnings it would be 8 × 1.07 = 8.56. 20 ignores the payout ratio.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-134","question":"A share trades at ₹125. Next year's EPS is ₹10 and the cost of equity is 12%. What is the present value of growth opportunities (PVGO) embedded in the price?","options":["₹83.33","₹41.67","₹115.00","₹13.33"],"answer":1,"explanation":"No-growth value = E₁/k = 10/0.12 = ₹83.33. PVGO = 125 − 83.33 = ₹41.67, about a third of the price.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-135","question":"Comparable companies trade at 8× EV/EBITDA. Your target has EBITDA of ₹50 crore, debt of ₹120 crore, cash of ₹20 crore and 10 crore shares. What value per share does the multiple imply?","options":["₹40.00","₹28.00","₹26.00","₹30.00"],"answer":3,"explanation":"EV = 8 × 50 = ₹400 crore. Equity = EV − debt + cash = 400 − 120 + 20 = ₹300 crore → ₹30 a share. ₹40 forgets debt; ₹28 forgets cash; ₹26 subtracts cash instead of adding it.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-136","question":"A company's EPS is ₹12 and similar companies trade at a P/E of 15. What price does relative valuation suggest?","options":["₹180","₹27","₹0.80","₹1,800"],"answer":0,"explanation":"Price = EPS × P/E = 12 × 15 = ₹180.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-137","question":"A company's shareholders' equity is ₹500 crore, it has 25 crore shares and the share price is ₹60. What is its price-to-book ratio?","options":["3.0","0.33","20.0","12.0"],"answer":0,"explanation":"Book value per share = 500/25 = ₹20; P/B = 60/20 = 3.0. 0.33 is the inverse; 20 is the book value per share.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-138","question":"Next year's free cash flow to equity is expected to be ₹40 crore, growing at 6% a year forever. The cost of equity is 14% and there are 5 crore shares. What is the value per share?","options":["₹106","₹57.14","₹100","₹50"],"answer":2,"explanation":"Equity value = FCFE₁/(Ke − g) = 40/0.08 = ₹500 crore → 500/5 = ₹100 a share. ₹106 grows the already-forward FCFE again; ₹57.14 ignores growth (40/0.14/5).","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-139","question":"Next year's free cash flow to the firm is ₹60 crore, growing at 5% forever. WACC is 11%, debt is ₹300 crore and there are 20 crore shares. What is the equity value per share?","options":["₹50.00","₹35.00","₹37.50","₹12.27"],"answer":1,"explanation":"Enterprise value = FCFF₁/(WACC − g) = 60/0.06 = ₹1,000 crore. Equity = 1,000 − 300 = ₹700 crore → ₹35 a share. ₹50 forgets to deduct debt; ₹37.50 grows the forward FCFF again (63/0.06); ₹12.27 ignores growth.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-140","question":"An investor puts 60% of her money in a stock expected to return 15% and 40% in a stock expected to return 10%. What is the portfolio's expected return?","options":["12.5%","12.0%","25.0%","13.0%"],"answer":3,"explanation":"Expected return = 0.6 × 15% + 0.4 × 10% = 9% + 4% = 13%. 12.5% is the simple average.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-141","question":"A stock returns 25% in a boom (probability 0.3), 12% in a normal year (0.5) and −5% in a recession (0.2). What is its expected return?","options":["10.67%","12.5%","14.5%","16.5%"],"answer":1,"explanation":"E(R) = 0.3 × 25 + 0.5 × 12 + 0.2 × (−5) = 7.5 + 6 − 1 = 12.5%. 10.67% is the unweighted average; 14.5% ignores the sign of the recession return.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-142","question":"For a stock with returns of 25%, 12% and −5% with probabilities 0.3, 0.5 and 0.2 (expected return 12.5%), what is the standard deviation of returns?","options":["1.08%","12.42%","6.01%","10.40%"],"answer":3,"explanation":"Variance = 0.3(12.5)² + 0.5(0.5)² + 0.2(17.5)² = 46.875 + 0.125 + 61.25 = 108.25 (%²). σ = √108.25 = 10.40%. Ignoring the probabilities gives 12.42%.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-143","question":"A portfolio holds 60% in asset A (σ = 20%) and 40% in asset B (σ = 10%); their correlation is 0.3. What is the portfolio's standard deviation?","options":["16.00%","12.65%","13.74%","13.21%"],"answer":2,"explanation":"σp² = 0.6²(20²) + 0.4²(10²) + 2(0.6)(0.4)(0.3)(20)(10) = 144 + 16 + 28.8 = 188.8; σp = 13.74%. 16% (the weighted average) holds only if ρ = 1; 12.65% assumes ρ = 0.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-144","question":"Two assets have standard deviations of 20% (A) and 10% (B) and are uncorrelated. What weight in A gives the minimum-variance portfolio?","options":["20%","33.3%","80%","50%"],"answer":0,"explanation":"With ρ = 0, w_A = σ_B²/(σ_A² + σ_B²) = 100/(400 + 100) = 20%. 33.3% uses standard deviations instead of variances; 80% is the weight in B.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-145","question":"A portfolio holds 40% in a stock with beta 1.5, 35% in a stock with beta 0.8 and 25% in a stock with beta 1.2. What is the portfolio beta?","options":["1.17","1.18","1.50","3.50"],"answer":1,"explanation":"Portfolio beta = 0.4 × 1.5 + 0.35 × 0.8 + 0.25 × 1.2 = 0.60 + 0.28 + 0.30 = 1.18. 1.17 is the simple average of the three betas.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-146","question":"Fund X returned 15% with a standard deviation of 20%; Fund Y returned 12% with a standard deviation of 12%. The risk-free rate is 6%. On a risk-adjusted (Sharpe) basis:","options":["X is better: excess return 9% vs 6%","X is better because its return is higher","Y is better: Sharpe 0.50 vs 0.45","They are equal: Sharpe 0.45 for both"],"answer":2,"explanation":"Sharpe = (Rp − Rf)/σp. X: (15 − 6)/20 = 0.45. Y: (12 − 6)/12 = 0.50. Y earns more excess return per unit of total risk.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-147","question":"A fund earned 16% with a beta of 1.2. The risk-free rate was 6% and the market returned 13%. What is its Jensen's alpha?","options":["+3.0%","−1.6%","+2.0%","+1.6%"],"answer":3,"explanation":"CAPM return = 6% + 1.2 × (13% − 6%) = 14.4%. Alpha = 16% − 14.4% = +1.6%. +3.0% compares the fund with the market return without adjusting for beta.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-148","question":"An analyst expects a stock to return 15%. Its beta is 1.4, the risk-free rate is 5% and the market return is 12%. Relative to the security market line, the stock is:","options":["Undervalued: required return 14.8% is below the expected 15%","Overvalued: required return 21.8% exceeds the expected 15%","Fairly valued: expected return equals the market return plus 3%","Overvalued: its beta is above 1"],"answer":0,"explanation":"Required = 5% + 1.4 × 7% = 14.8%. The expected 15% plots above the SML, so the stock offers more than it needs to: it is undervalued (buy). 21.8% wrongly uses 1.4 × 12%.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-149","question":"The covariance between a stock's returns and the market's returns is 0.024, and the market's standard deviation is 20%. What is the stock's beta?","options":["0.12","1.67","0.60","0.30"],"answer":2,"explanation":"β = Cov(i, m)/σm² = 0.024/0.04 = 0.60. Dividing by σm (0.20) instead of σm² gives 0.12.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-150","question":"A stock has a total standard deviation of 30% and a beta of 1.2; the market's standard deviation is 20%. What share of the stock's total variance is systematic?","options":["64%","80%","36%","120%"],"answer":0,"explanation":"Systematic variance = β²σm² = 1.44 × 400 = 576; total variance = 30² = 900. Share = 576/900 = 64% (the remaining 36% is diversifiable). 80% compares standard deviations (24/30) instead of variances.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-151","question":"When a company sells its shares to the public for the first time through an IPO, the transaction takes place in the:","options":["Secondary market","Money market","Derivatives market","Primary market"],"answer":3,"explanation":"New securities issued by the company (IPO, FPO, rights issue) are sold in the primary market; the money goes to the issuer. Later trading among investors happens in the secondary market.","difficulty":"easy","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-152","question":"In a book-built IPO with a price band, a retail investor who bids at the 'cut-off' price is agreeing to:","options":["Buy only at the lowest price in the band","Buy at whatever final issue price is discovered within the band","Buy at the price at which the shares list on the exchange","Sell the shares on listing day at the cut-off price"],"answer":1,"explanation":"Bidding at cut-off means accepting the final price set after the book is built; the investor blocks money at the upper end of the band and any excess is released.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-153","question":"Which statements correctly contrast futures with forwards? I. Futures are standardised and exchange-traded. II. Futures are marked to market daily. III. Forwards carry more counterparty risk than exchange-traded futures.","options":["I and II only","I, II and III","I and III only","II only"],"answer":1,"explanation":"Futures are standardised, cleared through a clearing corporation and settled daily through margins, which nearly removes counterparty risk. Forwards are private OTC contracts settled at maturity, so default risk remains.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-154","question":"An investor buys a call option with a strike price of ₹500 for a premium of ₹20. At expiry the share is at ₹560. What is the profit per share?","options":["₹60","₹80","₹40","−₹20"],"answer":2,"explanation":"Payoff = max(560 − 500, 0) = ₹60; profit = 60 − 20 = ₹40. ₹60 ignores the premium paid.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-155","question":"An investor buys a put with a strike of ₹300 for a premium of ₹15. What are the break-even price and the profit if the share ends at ₹270?","options":["Break-even ₹315; profit ₹30","Break-even ₹285; profit ₹30","Break-even ₹315; loss ₹15","Break-even ₹285; profit ₹15"],"answer":3,"explanation":"A long put breaks even at strike − premium = 300 − 15 = ₹285. At ₹270 the payoff is 300 − 270 = 30, so profit = 30 − 15 = ₹15.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-156","question":"A trader writes (sells) a call with a strike of ₹1,000 for a premium of ₹40. At expiry the underlying is at ₹1,100. What is the writer's profit or loss?","options":["Loss of ₹60","Profit of ₹40","Loss of ₹100","Profit of ₹60"],"answer":0,"explanation":"The buyer exercises: the writer pays 1,100 − 1,000 = ₹100 but kept the ₹40 premium, so net loss = ₹60. A call writer's loss is unlimited as the price rises.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-157","question":"A trader buys a call and a put on the same share, both with strike ₹200, for premiums of ₹12 and ₹8. What are the break-even prices and the profit if the share ends at ₹230?","options":["Break-evens ₹188 and ₹212; profit ₹18","Break-evens ₹180 and ₹220; profit ₹10","Break-evens ₹180 and ₹220; profit ₹30","Break-evens ₹192 and ₹212; profit ₹10"],"answer":1,"explanation":"Long straddle cost = 12 + 8 = ₹20, so break-evens are 200 ± 20 = ₹180 and ₹220. At ₹230 the call pays 30, the put expires worthless: profit = 30 − 20 = ₹10.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-158","question":"A trader buys a ₹100-strike call for ₹8 and sells a ₹110-strike call on the same share and expiry for ₹3. What are the maximum profit and the break-even price?","options":["Maximum profit ₹10; break-even ₹105","Maximum profit ₹5; break-even ₹108","Unlimited profit; break-even ₹105","Maximum profit ₹5; break-even ₹105"],"answer":3,"explanation":"Bull call spread: net debit = 8 − 3 = ₹5. Maximum payoff is the strike gap, 110 − 100 = 10, so maximum profit = 10 − 5 = ₹5 (at ₹110 or above). Break-even = lower strike + net debit = ₹105.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-159","question":"A trader buys one futures lot of 500 units at ₹1,200. Initial margin is 10% of contract value and maintenance margin is 75% of the initial margin. Next day the price settles at ₹1,150. How much variation margin must he deposit?","options":["₹25,000","₹10,000","₹0","₹15,000"],"answer":0,"explanation":"Initial margin = 10% × 500 × 1,200 = ₹60,000; maintenance = ₹45,000. MTM loss = 500 × 50 = ₹25,000, leaving ₹35,000, below maintenance. He must restore the account to the initial ₹60,000, i.e. deposit ₹25,000. ₹10,000 only tops up to the maintenance level.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-160","question":"A share trades at ₹2,000 and will pay a dividend of ₹40 in exactly one year. The risk-free rate is 9% a year (annual compounding). What is the fair 1-year forward price?","options":["₹2,180","₹2,220","₹2,140","₹1,960"],"answer":2,"explanation":"F = S(1 + r) − FV of income = 2,000 × 1.09 − 40 = 2,180 − 40 = ₹2,140. ₹2,180 ignores the dividend the forward buyer will not receive; ₹2,220 adds it.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-161","question":"A European call on a non-dividend share costs ₹8. The share price is ₹100, the strike ₹105, time to expiry 1 year and the risk-free rate 5% (annual compounding). By put–call parity, what should the matching put cost?","options":["₹13.00","₹3.00","₹5.00","₹8.00"],"answer":3,"explanation":"C + K/(1 + r) = P + S → P = 8 + 105/1.05 − 100 = 8 + 100 − 100 = ₹8. ₹13 forgets to discount the strike.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-162","question":"A call with a strike of ₹450 trades at a premium of ₹42 when the share is at ₹480. What are its intrinsic value and time value?","options":["Intrinsic ₹42; time value ₹0","Intrinsic ₹12; time value ₹30","Intrinsic ₹30; time value ₹12","Intrinsic ₹0; time value ₹42"],"answer":2,"explanation":"Intrinsic value of a call = max(S − K, 0) = 480 − 450 = ₹30. Time value = premium − intrinsic = 42 − 30 = ₹12.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-163","question":"A share trades at ₹470. Which statements are true? I. A call with strike ₹500 is out of the money. II. A put with strike ₹500 is in the money. III. That put's intrinsic value is ₹30.","options":["I and II only","I, II and III","II and III only","I only"],"answer":1,"explanation":"A call is in the money when S > K and a put when S < K. With S = 470 < 500 the call is out of the money and the put in the money, with intrinsic value 500 − 470 = ₹30.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-164","question":"The spot rate is ₹80.00 per US dollar. One-year interest rates are 7% in India and 4% in the US. By covered interest parity, what is the 1-year forward rate?","options":["₹82.31/$","₹82.40/$","₹77.76/$","₹80.00/$"],"answer":0,"explanation":"F = S × (1 + r_INR)/(1 + r_USD) = 80 × 1.07/1.04 = ₹82.31. The higher-interest currency trades at a forward discount. ₹82.40 is the approximation 80 × (1 + 3%); ₹77.76 inverts the ratio.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-165","question":"A company with a floating-rate loan enters a plain-vanilla interest rate swap in which it pays fixed and receives floating. It gains from the swap if:","options":["Floating rates fall below the fixed swap rate","The rupee depreciates","The swap's notional principal is exchanged at maturity","Floating rates rise above the fixed swap rate"],"answer":3,"explanation":"Paying fixed and receiving floating converts the floating loan into a fixed one. If floating rates rise, the floating leg it receives grows while its fixed payment stays the same. Notional principal is not exchanged in an interest rate swap.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-166","question":"What is the purpose of a green-shoe option in a public issue?","options":["It allows promoters to sell their entire stake on listing day","It lets retail investors withdraw bids after the issue closes","It lets the issue's stabilising agent over-allot shares and buy them back in the market to support the price after listing","It guarantees investors a minimum listing-day return"],"answer":2,"explanation":"Over-allotted shares create a short position; if the price falls below the issue price, the stabilising agent buys shares in the market, supporting the price. If the price rises, the company issues the extra shares instead.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-167","question":"A share trades at ₹120 cum-rights. The company offers 1 new share for every 4 held at ₹80. What are the theoretical ex-rights price and the value of the right attached to each existing share?","options":["₹112 and ₹8","₹112 and ₹32","₹104 and ₹16","₹110 and ₹10"],"answer":0,"explanation":"TERP = (4 × 120 + 1 × 80)/5 = 560/5 = ₹112. Value of a right per existing share = 120 − 112 = ₹8 (equivalently (112 − 80)/4). ₹32 is the gain per NEW share.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-168","question":"A fund manager holds a ₹50 lakh equity portfolio with a beta of 1.2. Index futures trade at 20,000 with a lot size of 50. How many futures contracts should she sell to hedge the portfolio fully?","options":["5 contracts","6 contracts","60 contracts","4 contracts"],"answer":1,"explanation":"Contract value = 20,000 × 50 = ₹10 lakh. Contracts = β × portfolio value/contract value = 1.2 × 50/10 = 6. Ignoring beta gives 5.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-169","question":"A miller wants to hedge 1,000 tonnes of wheat. Monthly changes in the spot price have σ = 2%, in the futures price σ = 2.5%, and their correlation is 0.9. Each futures contract covers 10 tonnes. How many contracts give the minimum-variance hedge?","options":["100 contracts","90 contracts","72 contracts","80 contracts"],"answer":2,"explanation":"Hedge ratio h* = ρ × σS/σF = 0.9 × 2/2.5 = 0.72. Contracts = 0.72 × 1,000/10 = 72. 100 is a naive one-for-one hedge; 80 ignores the correlation (2/2.5 = 0.8).","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-170","question":"In India's capital market, which entity holds investors' securities in electronic (dematerialised) form?","options":["A depository, through its depository participants","The stock exchange's trading member","The registrar to the issue","The merchant banker that managed the issue"],"answer":0,"explanation":"Depositories hold securities in electronic book-entry form; investors access them through depository participants (banks, brokers) where their demat accounts are opened.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-171","question":"In exchange-traded options, which party is normally required to deposit margin, and why?","options":["The option buyer, because the buyer can lose more than the premium","Both parties equally, because both face unlimited losses","Neither party, because premiums are paid upfront","The option writer, because only the writer has an open obligation that could lead to losses"],"answer":3,"explanation":"The buyer's maximum loss is the premium already paid, so no further margin is needed. The writer must perform if the option is exercised and can lose much more, so the clearing house collects margin from the writer.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-172","question":"An investor owns a share bought at ₹500 and writes a call on it with a strike of ₹540 for ₹15 (covered call). At expiry the share is at ₹600. What is her total profit per share?","options":["₹115","₹55","₹100","₹15"],"answer":1,"explanation":"The call is exercised, so she sells at ₹540: share gain = 540 − 500 = 40, plus the ₹15 premium = ₹55. Her upside is capped; ₹115 ignores that the share is called away.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-173","question":"An investor buys a share at ₹400 and a put with a strike of ₹380 for ₹10 (protective put). What is his maximum possible loss per share?","options":["₹10","₹20","₹410","₹30"],"answer":3,"explanation":"Below ₹380 the put offsets further falls, so the worst case is selling at 380: loss on share = 20, plus premium 10 = ₹30.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-174","question":"A 91-day Treasury bill with face value ₹100 is bought for ₹98.25. What is its annualised yield (365-day basis, simple)?","options":["7.02%","1.75%","7.14%","7.05%"],"answer":2,"explanation":"Yield = [(100 − 98.25)/98.25] × 365/91 = 1.7812% × 4.011 = 7.14%. 7.02% is the discount yield on face value; 1.75% is the 91-day return unannualised.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-175","question":"Match each money-market instrument with its feature. (p) Treasury bill, (q) Commercial paper, (r) Certificate of deposit, (s) Call money. Features: (1) Unsecured short-term promissory note issued by a highly rated company; (2) Overnight inter-bank borrowing and lending; (3) Discounted short-term government security; (4) Negotiable time deposit issued by a bank.","options":["p-1, q-3, r-4, s-2","p-3, q-1, r-4, s-2","p-3, q-4, r-1, s-2","p-3, q-1, r-2, s-4"],"answer":1,"explanation":"T-bills are discounted government securities (3); CP is an unsecured note of a highly rated corporate (1); a CD is a negotiable bank time deposit (4); call money is overnight inter-bank lending (2).","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-176","question":"A bank earns ₹900 crore of interest, pays ₹600 crore of interest and has average earning assets of ₹10,000 crore. What is its net interest margin?","options":["3.0%","9.0%","6.0%","33.3%"],"answer":0,"explanation":"NIM = (interest earned − interest paid)/average earning assets = 300/10,000 = 3%. 9% is the yield on assets; 33.3% divides net interest by interest income.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-177","question":"A bank has current deposits of ₹2,000 crore, savings deposits of ₹5,000 crore and term deposits of ₹13,000 crore. What is its CASA ratio?","options":["53.8%","35%","25%","65%"],"answer":1,"explanation":"CASA ratio = (current + savings)/total deposits = 7,000/20,000 = 35%. 53.8% divides by term deposits only; 65% is the term-deposit share.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-178","question":"A bank's gross advances are ₹10,000 crore, gross NPAs ₹600 crore and NPA provisions ₹360 crore. What is its net NPA ratio?","options":["2.40%","6.00%","2.49%","3.60%"],"answer":2,"explanation":"Net NPA = 600 − 360 = ₹240 crore. Net advances = 10,000 − 360 = ₹9,640 crore. Net NPA ratio = 240/9,640 = 2.49%. 2.40% divides by gross advances; 6% is the gross NPA ratio.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-179","question":"A bank has gross NPAs of ₹600 crore and has made provisions of ₹360 crore against them. What is its provision coverage ratio?","options":["60%","40%","3.6%","166.7%"],"answer":0,"explanation":"PCR = provisions/gross NPAs = 360/600 = 60%. A higher PCR means more of the bad loans are already provided for. 40% is the unprovided share.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-180","question":"A bank has Tier 1 capital of ₹800 crore and Tier 2 capital of ₹300 crore. Its assets: corporate loans ₹10,000 crore (risk weight 100%), home loans ₹4,000 crore (50%) and government securities ₹6,000 crore (0%). What is its capital-to-risk-weighted-assets ratio?","options":["5.50%","6.67%","7.86%","9.17%"],"answer":3,"explanation":"RWA = 10,000 × 1 + 4,000 × 0.5 + 6,000 × 0 = ₹12,000 crore. CRAR = (800 + 300)/12,000 = 9.17%. 5.50% divides by total assets (₹20,000 crore); 6.67% is the Tier 1 ratio only.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-181","question":"Match the Basel framework pillars with their content. (p) Pillar 1, (q) Pillar 2, (r) Pillar 3. Content: (1) Disclosure requirements that allow market discipline; (2) Minimum capital for credit, market and operational risk; (3) Supervisory review of the bank's internal capital assessment.","options":["p-1, q-2, r-3","p-2, q-3, r-1","p-3, q-2, r-1","p-2, q-1, r-3"],"answer":1,"explanation":"Pillar 1 sets minimum capital requirements; Pillar 2 is the supervisory review process (including the bank's own capital assessment); Pillar 3 is market discipline through disclosure.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-182","question":"A bank receives fresh deposits of ₹1,000 crore. It must keep 4% as cash reserves with the central bank and invest 18% in approved liquid securities. Ignoring other uses, how much is available for lending?","options":["₹960 crore","₹820 crore","₹220 crore","₹780 crore"],"answer":3,"explanation":"Pre-emptions = 4% + 18% = 22% of deposits = ₹220 crore. Lendable funds = 1,000 − 220 = ₹780 crore. ₹960 crore deducts only the cash reserve; ₹220 crore is the amount locked up.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-183","question":"A bank funds itself with deposits of ₹8,000 crore at 5.5% and borrowings of ₹1,000 crore at 7%. It holds advances of ₹6,000 crore yielding 9.5% and investments of ₹3,000 crore yielding 7%. What are its net interest income and NIM on earning assets?","options":["₹270 crore and 2.70%","₹780 crore and 8.67%","₹270 crore and 3.00%","₹200 crore and 2.22%"],"answer":2,"explanation":"Interest income = 6,000 × 9.5% + 3,000 × 7% = 570 + 210 = ₹780 crore. Interest expense = 8,000 × 5.5% + 1,000 × 7% = 440 + 70 = ₹510 crore. NII = ₹270 crore; NIM = 270/9,000 = 3.00%. 2.70% divides by an assumed ₹10,000 crore.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-184","question":"Assertion (A): A bank that funds 20-year fixed-rate home loans mainly with one-year deposits is hurt when interest rates rise. Reason (R): Its liabilities reprice faster than its assets, so its cost of funds rises while its loan yields stay fixed.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A. The maturity/repricing mismatch squeezes net interest income when rates rise — the core of asset–liability management.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-185","question":"A bank has rate-sensitive assets of ₹5,000 crore and rate-sensitive liabilities of ₹6,500 crore over the next year. If all rates rise by 1 percentage point, what is the approximate change in its net interest income?","options":["Rises by ₹15 crore","Falls by ₹115 crore","Falls by ₹15 crore","Rises by ₹50 crore"],"answer":2,"explanation":"Repricing gap = RSA − RSL = 5,000 − 6,500 = −₹1,500 crore. ΔNII ≈ gap × Δr = −1,500 × 1% = −₹15 crore. A negative gap means more liabilities than assets reprice, so rising rates hurt.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-186","question":"A bank has net profit of ₹1,200 crore, total assets of ₹1,00,000 crore and equity of ₹8,000 crore. What are its ROA and ROE?","options":["ROA 12%; ROE 1.5%","ROA 1.2%; ROE 15%","ROA 1.2%; ROE 1.2%","ROA 8%; ROE 15%"],"answer":1,"explanation":"ROA = 1,200/1,00,000 = 1.2%. ROE = 1,200/8,000 = 15%. ROE = ROA × equity multiplier = 1.2% × 12.5. Banks earn high ROE from low ROA through high leverage.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-187","question":"A company's net profit margin is 8%, asset turnover 1.5 times and equity multiplier 2. If it raises its equity multiplier to 2.5 with margin and turnover unchanged, what happens to ROE?","options":["It rises from 24% to 30%","It rises from 11.5% to 12%","It rises from 24% to 25%","It stays at 24%"],"answer":0,"explanation":"DuPont: ROE = margin × turnover × equity multiplier = 8% × 1.5 × 2 = 24%; with a multiplier of 2.5, ROE = 8% × 1.5 × 2.5 = 30%. Adding the factors (11.5%) is wrong.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-188","question":"A firm pays out 40% of its earnings and wants to grow at 12% a year without issuing new equity or changing its leverage. What return on equity must it earn?","options":["30%","12%","18%","20%"],"answer":3,"explanation":"Sustainable growth g = ROE × retention. Retention = 60%, so ROE = 12%/0.6 = 20%. 30% divides by the payout ratio instead of the retention ratio.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-189","question":"A firm with 40% debt (pre-tax cost 10%) and 60% equity (cost 16%) pays tax at 30%. A project of average risk costs ₹50 lakh and returns ₹15 lakh a year for 5 years. Which conclusion is correct?","options":["Reject: at the 16% cost of equity the NPV is about −₹0.89 lakh","Accept: at a WACC of 13.6% the NPV is about ₹2.00 lakh","Accept: at a WACC of 12.4% the NPV is about ₹3.54 lakh","Reject: the payback of 3.33 years exceeds the 3-year norm"],"answer":2,"explanation":"WACC = 0.6 × 16% + 0.4 × 10% × 0.7 = 9.6% + 2.8% = 12.4%. NPV = 15 × annuity factor(12.4%, 5) − 50 = 15 × 3.5693 − 50 ≈ ₹3.54 lakh > 0, so accept. Discounting at the cost of equity wrongly rejects it; 13.6% forgets the tax shield on debt.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-190","question":"A company's EBIT is ₹160 crore, its tax rate 25%, capital employed ₹800 crore and WACC 12%. What is its economic value added (EVA)?","options":["₹24 crore","₹64 crore","₹120 crore","₹96 crore"],"answer":0,"explanation":"NOPAT = 160 × (1 − 0.25) = ₹120 crore. Capital charge = 12% × 800 = ₹96 crore. EVA = 120 − 96 = ₹24 crore. ₹64 crore uses pre-tax EBIT.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-191","question":"A bank lends ₹10 lakh at 10% a year but requires the borrower to keep a compensating balance of 20% of the loan in a non-interest account. What is the effective cost of the loan?","options":["10.00%","12.50%","12.00%","8.00%"],"answer":1,"explanation":"Interest = ₹1 lakh; usable funds = 10 − 2 = ₹8 lakh. Effective cost = 1/8 = 12.5%. 12% simply adds 20% of 10%.","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-192","question":"A one-year loan of ₹10 lakh carries 12% interest deducted in advance (discount basis) and also requires a 10% compensating balance. What is the effective annual cost?","options":["13.64%","13.33%","12.00%","15.38%"],"answer":3,"explanation":"Usable funds = 10 − 1.2 (interest deducted) − 1.0 (compensating balance) = ₹7.8 lakh. Effective cost = 1.2/7.8 = 15.38%. 13.64% allows only for the discount; 13.33% allows only for the balance.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-193","question":"Which statements about bond price sensitivity to interest rates are correct? I. Other things equal, longer maturity means greater sensitivity. II. Other things equal, a higher coupon means greater sensitivity. III. A zero-coupon bond's Macaulay duration equals its maturity.","options":["I and III only","I, II and III","I and II only","II and III only"],"answer":0,"explanation":"Longer maturity raises duration (I). A higher coupon returns more cash earlier, LOWERING duration and sensitivity, so II is false. A zero has a single cash flow at maturity, so its duration equals maturity (III).","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-194","question":"A mutual fund scheme has assets of ₹520 crore, liabilities of ₹20 crore and 40 crore units outstanding. What is its NAV per unit?","options":["₹13.00","₹12.50","₹12.00","₹10.00"],"answer":1,"explanation":"NAV = (assets − liabilities)/units = (520 − 20)/40 = ₹12.50. ₹13.00 ignores liabilities.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-195","question":"An investor puts ₹6,000 into a fund every month for three months at NAVs of ₹20, ₹24 and ₹30. What is her average cost per unit?","options":["₹24.67","₹25.00","₹24.00","₹30.00"],"answer":2,"explanation":"Units = 300 + 250 + 200 = 750 for ₹18,000, so average cost = 18,000/750 = ₹24.00, below the average NAV of ₹24.67. Equal rupee amounts buy more units when prices are low (rupee-cost averaging).","difficulty":"hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-196","question":"₹1 lakh invested in a fund becomes ₹1.5 lakh after one year and ₹1.2 lakh after two years. Which statement is correct?","options":["Both the average return and the CAGR are 15%","The CAGR is 10% and the average return is 9.54%","The CAGR is 15% because the gain was earned in year 1","Average annual return is 15% but the CAGR is only 9.54%"],"answer":3,"explanation":"Yearly returns are +50% and −20%: arithmetic average = 15%. CAGR = (1.2/1.0)^(1/2) − 1 = 9.54%. The arithmetic average overstates the compound return whenever returns are volatile; 10% is the simple (20%/2) annual gain.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-197","question":"A bank's exposure to a borrower is ₹50 crore. The probability of default over the year is 2% and the loss given default is 45%. What is the expected credit loss?","options":["₹1 crore","₹22.5 crore","₹45 lakh","₹4.5 crore"],"answer":2,"explanation":"EL = PD × LGD × EAD = 0.02 × 0.45 × 50 crore = ₹0.45 crore = ₹45 lakh. ₹1 crore ignores recoveries (assumes LGD = 100%); ₹22.5 crore omits the default probability.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-198","question":"A stock has a beta of 1.25; the risk-free rate is 6% and the market risk premium 8%. It trades at ₹75 and next year's dividend is expected to be ₹6. What constant growth rate is the market implying?","options":["10.0%","6.0%","24.0%","8.0%"],"answer":3,"explanation":"Ke = 6% + 1.25 × 8% = 16%. From P₀ = D₁/(Ke − g): g = Ke − D₁/P₀ = 16% − 6/75 = 16% − 8% = 8%.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-199","question":"A firm's target debt–equity ratio is 0.5. Its cost of equity is 15%, its pre-tax cost of debt 9% and its tax rate 30%. What is its WACC?","options":["12.10%","10.65%","13.00%","9.17%"],"answer":0,"explanation":"D/E = 0.5 means D/V = 0.5/1.5 = 1/3 and E/V = 2/3. WACC = (2/3)(15%) + (1/3)(9% × 0.7) = 10% + 2.1% = 12.10%. Treating 0.5 as the debt weight gives 10.65%; ignoring tax gives 13.00%.","difficulty":"very-hard","source":"Finance analyst · Bank MT · MBA placement pattern"},
  {"id":"mgmt-finance-200","question":"Assertion (A): A higher share of CASA deposits generally lowers a bank's cost of funds. Reason (R): Current accounts usually pay no interest and savings accounts pay lower rates than term deposits.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: cheap current and savings deposits pull down the average cost of deposits, which supports the bank's NIM.","difficulty":"moderate","source":"Finance analyst · Bank MT · MBA placement pattern"},
];

export default questions;
